"""Small, standard-library client for private text prompts via OpenAI Responses.

The client does not log prompts or responses and asks the API not to store the
response.  ``store=False`` is not a promise of zero data retention; applicable
OpenAI account and API data-control policies still govern processing.
"""

from __future__ import annotations

import json
import os
import ssl
import urllib.error
import urllib.request
from typing import Any, Mapping, Optional


RESPONSES_URL = "https://api.openai.com/v1/responses"


class OpenAIError(RuntimeError):
    """Raised when a request cannot be completed successfully."""


def _output_text(response: Mapping[str, Any]) -> str:
    """Extract assistant text from a Responses API response."""
    direct = response.get("output_text")
    if isinstance(direct, str):
        return direct

    parts = []
    for item in response.get("output", []):
        if not isinstance(item, Mapping) or item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if not isinstance(content, Mapping):
                continue
            if content.get("type") in ("output_text", "text"):
                text = content.get("text")
                if isinstance(text, str):
                    parts.append(text)
    if parts:
        return "".join(parts)
    raise OpenAIError("The API response contained no text output")


def send_prompt(
    prompt: str,
    *,
    model: Optional[str] = None,
    api_key: Optional[str] = None,
    timeout: float = 60.0,
) -> str:
    """Send a text prompt and return the response text.

    The API key defaults to ``OPENAI_API_KEY``. The model defaults to
    ``OPENAI_MODEL`` and must otherwise be supplied explicitly. The request
    always sets ``store`` to false.
    """
    if not isinstance(prompt, str) or not prompt:
        raise ValueError("prompt must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")

    resolved_key = api_key or os.environ.get("OPENAI_API_KEY")
    if not resolved_key:
        raise OpenAIError("Set OPENAI_API_KEY or pass api_key explicitly")
    resolved_model = model or os.environ.get("OPENAI_MODEL")
    if not resolved_model:
        raise OpenAIError("Set OPENAI_MODEL or pass model explicitly")

    body = json.dumps(
        {"model": resolved_model, "input": prompt, "store": False},
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    request = urllib.request.Request(
        RESPONSES_URL,
        data=body,
        headers={
            "Authorization": "Bearer " + resolved_key,
            "Content-Type": "application/json",
            "User-Agent": "stdlib-openai-client/1.0",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(
            request, timeout=timeout, context=ssl.create_default_context()
        ) as result:
            raw = result.read()
    except urllib.error.HTTPError as exc:
        # Do not echo the server body: it could contain sensitive request data.
        raise OpenAIError(f"OpenAI API returned HTTP {exc.code}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise OpenAIError("Could not reach the OpenAI API") from exc

    try:
        decoded = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIError("OpenAI API returned an invalid JSON response") from exc
    if not isinstance(decoded, Mapping):
        raise OpenAIError("OpenAI API returned an unexpected response")
    return _output_text(decoded)


__all__ = ["OpenAIError", "send_prompt"]
